  "instagramConnect.invalidRedirectStep1": "Open the Instagram app (e.g. Vialdi ID-IG), not the Facebook app.",
  "instagramConnect.invalidRedirectStep2": "Go to: Instagram → API setup with Instagram business login → Business login settings.",
  "instagramConnect.invalidRedirectStep3": "In OAuth redirect URIs add exactly the URL above (no space, no trailing slash). Save.",
  "instagramConnect.invalidRedirectStep4": "Also add the same URL in the Facebook app: Use cases → Facebook Login for Business → Client OAuth → Valid OAuth Redirect URIs.",
